// Discriminated union — the real power
type Shape = // creates reusable type alias
  | { kind: 'circle'; radius: number }
  | { kind: 'square'; side: number }
  | { kind: 'triangle'; base: number; height: number };

function area(s: Shape): number { // defines reusable function block
  switch (s.kind) { // branches execution on value match
    case 'circle': return Math.PI * s.radius ** 2; // matches and handles specific value
    case 'square': return s.side ** 2; // matches and handles specific value
    case 'triangle': return (s.base * s.height) / 2; // matches and handles specific value
  }
}

// Exhaustiveness check — never ignore a case
function assertNever(x: never): never { // defines reusable function block
  throw new Error('Unexpected case'); // intentionally raises an error
}

