Mixins:
type Constructor<T = {}> = new (...args: any[]) => T; // creates reusable type alias

function Timestamped<TBase extends Constructor>(Base: TBase) { // defines reusable function block
  return class extends Base { // returns value to calling code
    timestamp = new Date();
  };
}
function Activatable<TBase extends Constructor>(Base: TBase) { // defines reusable function block
  return class extends Base { // returns value to calling code
    isActive = false;
    toggle() { this.isActive = !this.isActive; } // defines class method
  };
}
class User { name: string = ''; } // defines a class blueprint
const TimestampedUser = Timestamped(Activatable(User)); // declares variable; type inferred
const user = new TimestampedUser(); // declares variable; type inferred
console.log(user.timestamp, user.isActive); // outputs message to developer console

