Conditional Types:
// Basic conditional
 type IsString<T> = T extends string ? true : false; // creates reusable type alias
 type A = IsString<'hello'>; // true
 type B = IsString<42>;       // false

 // Distribution over unions
 type C = IsString<string | number>; // creates reusable type alias
 // true | false = boolean (distributes)

 // infer — capture a type
 type ReturnType<T> = T extends (...args: any[]) => infer R ? R : never; // creates reusable type alias
 type Fn = (x: number) => string; // creates reusable type alias
 type R = ReturnType<Fn>; // string

 // Real-world: unwrap promises
 type PromiseValue<T> = T extends Promise<infer V> ? V : T; // creates reusable type alias
 type PV = PromiseValue<Promise<number>>; // number
 type PV2 = PromiseValue<string>; // string (pass-through)

 // Filter types with conditional
 type NonNullable<T> = T extends null | undefined ? never : T; // creates reusable type alias
 type Clean = NonNullable<string | null | undefined>; // string

 // Chained conditionals (like if/else if/else)
 type TypeName<T> = // creates reusable type alias
   T extends string ? 'string' :
   T extends number ? 'number' :
   T extends boolean ? 'boolean' :
   T extends undefined ? 'undefined' :
   T extends Function ? 'function' :
   'object';

