Discriminated Unions:
// ❌ Bad: scattered optionals
interface AsyncStateBad { // defines object shape contract
  loading: boolean;
  data?: Data;
  error?: string;
}
// You can have loading=true AND data at the same time — invalid!

// ✅ Good: discriminated union
 type AsyncState<T> = // creates reusable type alias
   | { status: 'loading' }
   | { status: 'success'; data: T }
   | { status: 'error'; error: string };

 function handleState(state: AsyncState<Data>) { // defines reusable function block
   switch (state.status) { // branches execution on value match
     case 'loading': // matches and handles specific value
       console.log('Loading...'); // outputs message to developer console
       break;
     case 'success': // matches and handles specific value
       console.log(state.data); // typed as Data
       break;
     case 'error': // matches and handles specific value
       console.error(state.error); // typed as string
       break;
   }
 }

 // Exhaustive check — compiler warns on new variants
 function assertNever(x: never): never { // defines reusable function block
   throw new Error('Unexpected variant'); // intentionally raises an error
 }

