Async Iterators:
async function* generateNumbers(): AsyncIterable<number> { // defines async function returning promise
  for (let i = 0; i < 3; i++) { // iterates with counter variable
    await new Promise(r => setTimeout(r, 100)); // waits for promise to resolve
    yield i; // emits next value from generator
  }
}

async function consume() { // defines async function returning promise
  for await (const num of generateNumbers()) {
    console.log(num); // 0, 1, 2
  }
}
// for...of would fail — must use for await...of

