async function safeFetch(url: string): Promise<unknown> { // defines async function returning promise
  try { // attempts code that might throw
    const res = await fetch(url); // declares variable; type inferred
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // conditionally executes following block
    return await res.json(); // returns value to calling code
  } catch (error: unknown) {
    if (error instanceof Error) { // conditionally executes following block
      console.error(error.message); // outputs message to developer console
    } else if (typeof error === 'string') {
      console.error(error); // outputs message to developer console
    } else {
      console.error('Unknown error', error); // outputs message to developer console
    }
    return null; // returns value to calling code
  }
}

